package com.lovelyshades.entity;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.math.*;
@Entity @Table(name="detalle_factura")
public class DetalleFactura { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_detalle_factura") private Long idDetalleFactura; @ManyToOne(optional=false) @JoinColumn(name="id_factura",nullable=false) private Factura factura; @ManyToOne(optional=false) @JoinColumn(name="id_producto",nullable=false) private Producto producto; @NotNull @Min(1) @Column(name="cantidad",nullable=false) private Integer cantidad; @Column(name="precio_unitario",nullable=false,precision=12,scale=2) private BigDecimal precioUnitario; @Column(name="subtotal",nullable=false,precision=12,scale=2) private BigDecimal subtotal; public Long getIdDetalleFactura(){return idDetalleFactura;} public void setIdDetalleFactura(Long idDetalleFactura){this.idDetalleFactura=idDetalleFactura;} public Factura getFactura(){return factura;} public void setFactura(Factura factura){this.factura=factura;} public Producto getProducto(){return producto;} public void setProducto(Producto producto){this.producto=producto;} public Integer getCantidad(){return cantidad;} public void setCantidad(Integer cantidad){this.cantidad=cantidad;} public BigDecimal getPrecioUnitario(){return precioUnitario;} public void setPrecioUnitario(BigDecimal precioUnitario){this.precioUnitario=precioUnitario;} public BigDecimal getSubtotal(){return subtotal;} public void setSubtotal(BigDecimal subtotal){this.subtotal=subtotal;} }
